              body: `export async function removeVault(path: string): Promise<Vault[]> {
    const store = await loadStore();
    const vaults = (await store.get<Vault[]>("vaults")) ?? [];

    // add all vaults into new array except one that matches path
    const updated_vaults = vaults.filter((v) => v.path !== path);

    await store.set("vaults", updated_vaults);

    // set last vault to last vault path
    const lastVault = await store.get<string>("lastVault");
    if (lastVault === path) {
        await store.delete("lastVault");

        if (updated_vaults.length > 0) {
            const lastVault = updated_vaults[updated_vaults.length - 1];
            await setLastVault(lastVault);
        }
    }

    return updated_vaults;
}`,
